<template><div class="option-page"><el-alert title="全部期权合约按品种汇总；可切换品种查看其全部合约代码与名称，不展示交易日。" type="info" :closable="false" show-icon /><el-form inline class="form"><el-form-item label="期权品种"><el-select v-model="selected" clearable filterable placeholder="全部品种" style="width:260px" @change="search"><el-option v-for="item in varieties" :key="`${item.exchangeCode}/${item.varietyCode}`" :label="`${item.exchangeCode}/${item.varietyCode} · ${item.name || ''}`" :value="`${item.exchangeCode}|${item.varietyCode}`" /></el-select></el-form-item></el-form><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="code" label="代码" width="150" /><el-table-column prop="name" label="品种" min-width="160" /><el-table-column prop="contractCodeSummary" label="合约代码汇总" min-width="420" show-overflow-tooltip /><el-table-column prop="nameSummary" label="名称汇总" min-width="220" show-overflow-tooltip /></el-table><pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="getList" /></div></template>
<script setup name="OptionContracts">
import { reactive, ref } from 'vue'
import { listOptionContracts, listOptionVarieties } from '@/api/future/option'
const loading = ref(false); const rows = ref([]); const total = ref(0); const varieties = ref([]); const selected = ref(); const query = reactive({ pageNum: 1, pageSize: 100, varietyCode: undefined, exchangeCode: undefined })
function getList(){ loading.value=true; listOptionContracts(query).then(response=>{ rows.value=response.data.rows||[]; total.value=response.data.total||0 }).finally(()=>{loading.value=false}) } function search(){[query.exchangeCode,query.varietyCode]=selected.value ? selected.value.split('|') : [undefined,undefined];query.pageNum=1;getList()} listOptionVarieties({pageNum:1,pageSize:100}).then(response=>{varieties.value=response.data.rows||[]}); getList()
</script><style scoped>.option-page{padding:20px}.form{margin-top:16px}</style>
